import { __decorate } from "tslib";
import { Component } from '@angular/core';
import { Validators } from '@angular/forms';
import { CreateFuncionarioFormComponent } from '../../create-funcionario-form/create-funcionario-form.component';
let PerfilComponent = class PerfilComponent {
    constructor(funcionarioService, fb, dialog) {
        this.funcionarioService = funcionarioService;
        this.fb = fb;
        this.dialog = dialog;
        this.displayedColumns = ['nome', 'id'];
        this.dataSource = [];
        this.formSearch = this.fb.group({
            search: ['', [Validators.required]],
            submit: ['']
        });
    }
    ngOnInit() {
    }
    /*async ngOnInit(){
    this.dataSource = await this.funcionarioService.findAll()
    }*/
    openCreateFuncionarioDialog() {
        this.dialog.open(CreateFuncionarioFormComponent, {
            width: '400px',
            height: '400px',
        });
    }
};
PerfilComponent = __decorate([
    Component({
        selector: 'app-perfil',
        templateUrl: './perfil.component.html',
        styleUrls: ['./perfil.component.css']
    })
], PerfilComponent);
export { PerfilComponent };
